/* PICO-8 drawing API: shapes, sprites, map, palettes, print, btnp, and
** no-op stubs for the not-yet subsystems. Portable C99, Calypsi-safe
** (no int64). Semantics tagged VERIFY need pinning against real PICO-8
** by the vector goldens. Font table generated by tools/mkfont.py from
** fake-08 (MIT). */
#include <string.h>
#include "p8.h"
#include "p8num.h"
#include "p8int.h"
#include "lua/lauxlib.h"

#include "p8font.h"

/* line state: 0x5f3c/0x5f3e endpoints (int16 LE), 0x5f35 bit0 = invalid
** (VERIFY: address of the validity flag) */
#define DS_LINE_X 0x5f3c
#define DS_LINE_Y 0x5f3e
#define DS_LINE_INVALID 0x5f35

static int rd16(unsigned int a)
{
  return (int)(int16_t)(p8_ram[a] | (p8_ram[a + 1] << 8));
}

static void wr16(unsigned int a, int v)
{
  p8_ram[a] = (uint8_t)(v & 0xFF);
  p8_ram[a + 1] = (uint8_t)((v >> 8) & 0xFF);
}

static int pen_or_arg(lua_State *L, int idx)
{
  if (!lua_isnoneornil(L, idx))
    p8_ram[P8_DS_PEN] = (uint8_t)(p8a_int(L, idx) & 0xFF);
  return p8_ram[P8_DS_PEN];
}

/* ---- lines ---- */

/* M9 T3: all walkers snapshot the draw state once (P8Ctx) and plot
** through it -- see p8int.h. Pen is resolved in the ctx by the caller. */
static void draw_line(const P8Ctx *k, int x0, int y0, int x1, int y1)
{
  int dx = x1 > x0 ? x1 - x0 : x0 - x1;
  int dy = y1 > y0 ? y1 - y0 : y0 - y1;
  int sx = x0 < x1 ? 1 : -1;
  int sy = y0 < y1 ? 1 : -1;
  int err = dx - dy;
  for (;;) {
    p8i_ctx_plot(k, x0, y0);
    if (x0 == x1 && y0 == y1)
      break;
    {
      int e2 = 2 * err;
      if (e2 > -dy) {
        err -= dy;
        x0 += sx;
      }
      if (e2 < dx) {
        err += dx;
        y0 += sy;
      }
    }
  }
}

static int api_line(lua_State *L)
{
  int argc = lua_gettop(L);
  if (argc == 0) {
    p8_ram[DS_LINE_INVALID] |= 1;
    return 0;
  }
  if (argc >= 4) {
    int x0 = p8a_int(L, 1), y0 = p8a_int(L, 2);
    int x1 = p8a_int(L, 3), y1 = p8a_int(L, 4);
    P8Ctx k;
    p8i_ctx_load(&k);
    p8i_ctx_pen(&k, pen_or_arg(L, 5));
    draw_line(&k, x0, y0, x1, y1);
    wr16(DS_LINE_X, x1);
    wr16(DS_LINE_Y, y1);
    p8_ram[DS_LINE_INVALID] &= (uint8_t)~1u;
    return 0;
  }
  {
    /* line(x1, y1, [col]): continue from the stored endpoint */
    int x1 = p8a_int(L, 1), y1 = p8a_int(L, 2);
    P8Ctx k;
    p8i_ctx_load(&k);
    p8i_ctx_pen(&k, pen_or_arg(L, 3));
    if (!(p8_ram[DS_LINE_INVALID] & 1))
      draw_line(&k, rd16(DS_LINE_X), rd16(DS_LINE_Y), x1, y1);
    else
      p8i_ctx_plot(&k, x1, y1); /* VERIFY: first point after line() */
    wr16(DS_LINE_X, x1);
    wr16(DS_LINE_Y, y1);
    p8_ram[DS_LINE_INVALID] &= (uint8_t)~1u;
    return 0;
  }
}

/* ---- rectangles ---- */

static void norm2(int *a, int *b)
{
  if (*a > *b) {
    int t = *a;
    *a = *b;
    *b = t;
  }
}

static int api_rect(lua_State *L)
{
  int x0 = p8a_int(L, 1), y0 = p8a_int(L, 2);
  int x1 = p8a_int(L, 3), y1 = p8a_int(L, 4);
  int x;
  P8Ctx k;
  norm2(&x0, &x1);
  norm2(&y0, &y1);
  p8i_ctx_load(&k);
  p8i_ctx_pen(&k, pen_or_arg(L, 5));
  for (x = x0; x <= x1; x++) {
    p8i_ctx_plot(&k, x, y0);
    p8i_ctx_plot(&k, x, y1);
  }
  for (x = y0 + 1; x < y1; x++) {
    p8i_ctx_plot(&k, x0, x);
    p8i_ctx_plot(&k, x1, x);
  }
  return 0;
}

static int api_rectfill(lua_State *L)
{
  int x0 = p8a_int(L, 1), y0 = p8a_int(L, 2);
  int x1 = p8a_int(L, 3), y1 = p8a_int(L, 4);
  int x, y;
  P8Ctx k;
  norm2(&x0, &x1);
  norm2(&y0, &y1);
  p8i_ctx_load(&k);
  p8i_ctx_pen(&k, pen_or_arg(L, 5));
  if (k.pat == 0) {
    /* M9 T3 span path: solid fill, so clip the rect once and fill each
       row byte-wise (2 px/byte; odd edges RMW their nibble -- x&1 is
       the HIGH nibble, matching p8i_screen_set). Bit-identical to the
       per-pixel loop: same camera/clip arithmetic, same nibble writes,
       just batched. */
    int beg = x0 - k.cam_x, end = x1 - k.cam_x;
    int ry0 = y0 - k.cam_y, ry1 = y1 - k.cam_y;
    uint8_t v = k.v_lo, vv = (uint8_t)(v | (v << 4));
    if (beg < k.clip_x0) beg = k.clip_x0;
    if (end >= k.clip_x1) end = k.clip_x1 - 1;
    if (ry0 < k.clip_y0) ry0 = k.clip_y0;
    if (ry1 >= k.clip_y1) ry1 = k.clip_y1 - 1;
    if (beg <= end && ry0 <= ry1) {
      int bx = beg >> 1, ex = end >> 1;
      uint8_t *row = &p8_ram[P8_SCREEN + (uint16_t)(ry0 * 64)];
      for (y = ry0; y <= ry1; y++, row += 64) {
        if (bx == ex) {
          uint8_t *p = row + bx;
          if ((beg & 1) == 0 && (end & 1) != 0)
            *p = vv;
          else if (beg & 1)
            *p = (uint8_t)((*p & 0x0F) | (v << 4));
          else
            *p = (uint8_t)((*p & 0xF0) | v);
        } else {
          uint8_t *p = row + bx;
          uint8_t *q = row + ex;
          if (beg & 1) {
            *p = (uint8_t)((*p & 0x0F) | (v << 4));
            p++;
          }
          if ((end & 1) == 0) {
            *q = (uint8_t)((*q & 0xF0) | v);
            q--;
          }
          if (q >= p)
            memset(p, vv, (size_t)(q - p + 1));
        }
      }
    }
    return 0;
  }
  for (y = y0; y <= y1; y++)
    for (x = x0; x <= x1; x++)
      p8i_ctx_plot(&k, x, y);
  return 0;
}

/* ---- circles (midpoint; VERIFY exact PICO-8 shape for small radii) ---- */

static void circ_spans(const P8Ctx *k, int cx, int cy, int r, int fill)
{
  int x = r, y = 0, err = 1 - r;
  if (r < 0)
    return;
  while (x >= y) {
    if (fill) {
      int i;
      for (i = -x; i <= x; i++) {
        p8i_ctx_plot(k, cx + i, cy + y);
        p8i_ctx_plot(k, cx + i, cy - y);
      }
      for (i = -y; i <= y; i++) {
        p8i_ctx_plot(k, cx + i, cy + x);
        p8i_ctx_plot(k, cx + i, cy - x);
      }
    } else {
      p8i_ctx_plot(k, cx + x, cy + y);
      p8i_ctx_plot(k, cx - x, cy + y);
      p8i_ctx_plot(k, cx + x, cy - y);
      p8i_ctx_plot(k, cx - x, cy - y);
      p8i_ctx_plot(k, cx + y, cy + x);
      p8i_ctx_plot(k, cx - y, cy + x);
      p8i_ctx_plot(k, cx + y, cy - x);
      p8i_ctx_plot(k, cx - y, cy - x);
    }
    y++;
    if (err < 0) {
      err += 2 * y + 1;
    } else {
      x--;
      err += 2 * (y - x) + 1;
    }
  }
}

static int api_circ(lua_State *L)
{
  int cx = p8a_int(L, 1), cy = p8a_int(L, 2);
  int r = p8a_optint(L, 3, 4);
  P8Ctx k;
  p8i_ctx_load(&k);
  p8i_ctx_pen(&k, pen_or_arg(L, 4));
  circ_spans(&k, cx, cy, r, 0);
  return 0;
}

static int api_circfill(lua_State *L)
{
  int cx = p8a_int(L, 1), cy = p8a_int(L, 2);
  int r = p8a_optint(L, 3, 4);
  P8Ctx k;
  p8i_ctx_load(&k);
  p8i_ctx_pen(&k, pen_or_arg(L, 4));
  circ_spans(&k, cx, cy, r, 1);
  return 0;
}

/* ---- ovals (axis-aligned, bounding box; VERIFY exact shape) ---- */

static void oval_draw(const P8Ctx *k, int x0, int y0, int x1, int y1, int fill)
{
  /* integer midpoint ellipse on the bounding box */
  int a, b, cx2, cy2, x, y;
  long a2, b2, err, e2;
  norm2(&x0, &x1);
  norm2(&y0, &y1);
  a = x1 - x0;
  b = y1 - y0;
  cx2 = x0 + x1; /* 2*center */
  cy2 = y0 + y1;
  a2 = (long)a * a;
  b2 = (long)b * b;
  x = -a;
  y = 0;
  err = b2 - (2 * (long)b - 1) * a2;
  do {
    int px0 = (cx2 + x) / 2, px1 = (cx2 - x + 1) / 2;
    int py0 = (cy2 - y + 1) / 2, py1 = (cy2 + y) / 2;
    if (fill) {
      int i;
      for (i = px0; i <= px1; i++) {
        p8i_ctx_plot(k, i, py0);
        p8i_ctx_plot(k, i, py1);
      }
    } else {
      p8i_ctx_plot(k, px0, py1);
      p8i_ctx_plot(k, px1, py1);
      p8i_ctx_plot(k, px0, py0);
      p8i_ctx_plot(k, px1, py0);
    }
    e2 = 2 * err;
    if (e2 >= (x * 2 + 1) * b2) {
      x++;
      err += (x * 2 + 1) * b2;
    }
    if (e2 <= (y * 2 + 1) * a2) {
      y++;
      err += (y * 2 + 1) * a2;
    }
  } while (x <= 0);
  return;
}

static int api_oval(lua_State *L)
{
  int x0 = p8a_int(L, 1), y0 = p8a_int(L, 2);
  int x1 = p8a_int(L, 3), y1 = p8a_int(L, 4);
  P8Ctx k;
  p8i_ctx_load(&k);
  p8i_ctx_pen(&k, pen_or_arg(L, 5));
  oval_draw(&k, x0, y0, x1, y1, 0);
  return 0;
}

static int api_ovalfill(lua_State *L)
{
  int x0 = p8a_int(L, 1), y0 = p8a_int(L, 2);
  int x1 = p8a_int(L, 3), y1 = p8a_int(L, 4);
  P8Ctx k;
  p8i_ctx_load(&k);
  p8i_ctx_pen(&k, pen_or_arg(L, 5));
  oval_draw(&k, x0, y0, x1, y1, 1);
  return 0;
}

/* ---- sprites ---- */

static int api_spr(lua_State *L)
{
  int n = p8a_int(L, 1) & 0xFF;
  int x = p8a_int(L, 2), y = p8a_int(L, 3);
  /* w/h can be fractional (0.5 = 4 pixels) */
  int pw = lua_isnoneornil(L, 4) ? 8
           : (int)p8fix_toint(p8fix_mul((long)lua_tonumber(L, 4), p8fix_fromint(8)));
  int ph = lua_isnoneornil(L, 5) ? 8
           : (int)p8fix_toint(p8fix_mul((long)lua_tonumber(L, 5), p8fix_fromint(8)));
  int fx = lua_toboolean(L, 6);
  int fy = lua_toboolean(L, 7);
  int sx0 = (n % 16) * 8, sy0 = (n / 16) * 8;
  int i, j;
  P8Ctx k;
  p8i_ctx_load(&k);
  for (j = 0; j < ph; j++)
    for (i = 0; i < pw; i++) {
      int si = fx ? pw - 1 - i : i;
      int sj = fy ? ph - 1 - j : j;
      p8i_ctx_sprite(&k, x + i, y + j, p8i_sheet_get(sx0 + si, sy0 + sj));
    }
  return 0;
}

static int api_sspr(lua_State *L)
{
  int sx = p8a_int(L, 1), sy = p8a_int(L, 2);
  int sw = p8a_int(L, 3), sh = p8a_int(L, 4);
  int dx = p8a_int(L, 5), dy = p8a_int(L, 6);
  int dw = p8a_optint(L, 7, sw), dh = p8a_optint(L, 8, sh);
  int fx = lua_toboolean(L, 9);
  int fy = lua_toboolean(L, 10);
  int i, j;
  if (dw < 0) { dw = -dw; fx = !fx; } /* VERIFY negative sizes */
  if (dh < 0) { dh = -dh; fy = !fy; }
  if (dw == 0 || dh == 0 || sw <= 0 || sh <= 0)
    return 0;
  {
    P8Ctx k;
    p8i_ctx_load(&k);
    for (j = 0; j < dh; j++)
      for (i = 0; i < dw; i++) {
        int si = (int)(((long)(fx ? dw - 1 - i : i) * sw) / dw);
        int sj = (int)(((long)(fy ? dh - 1 - j : j) * sh) / dh);
        p8i_ctx_sprite(&k, dx + i, dy + j, p8i_sheet_get(sx + si, sy + sj));
      }
  }
  return 0;
}

/* ---- map ---- */

static unsigned int map_addr(int cx, int cy)
{
  cx &= 127;
  if (cy < 0 || cy > 63)
    return 0xFFFFFFFFu;
  if (cy < 32)
    return P8_MAP + (unsigned int)(cy * 128 + cx);
  return 0x1000u + (unsigned int)((cy - 32) * 128 + cx); /* shared w/ gfx */
}

static int api_mget(lua_State *L)
{
  unsigned int a = map_addr(p8a_int(L, 1), p8a_int(L, 2));
  lua_pushnumber(L, (lua_Number)p8fix_fromint(a == 0xFFFFFFFFu ? 0 : p8_ram[a]));
  return 1;
}

static int api_mset(lua_State *L)
{
  unsigned int a = map_addr(p8a_int(L, 1), p8a_int(L, 2));
  if (a != 0xFFFFFFFFu)
    p8_ram[a] = (uint8_t)(p8a_int(L, 3) & 0xFF);
  return 0;
}

static int api_map(lua_State *L)
{
  int cx = p8a_optint(L, 1, 0), cy = p8a_optint(L, 2, 0);
  int sx = p8a_optint(L, 3, 0), sy = p8a_optint(L, 4, 0);
  int cw = p8a_optint(L, 5, 128), ch = p8a_optint(L, 6, 32);
  int layer = p8a_optint(L, 7, 0) & 0xFF;
  int i, j;
  P8Ctx k;
  p8i_ctx_load(&k);
  for (j = 0; j < ch; j++)
    for (i = 0; i < cw; i++) {
      unsigned int a = map_addr(cx + i, cy + j);
      uint8_t n = (a == 0xFFFFFFFFu) ? 0 : p8_ram[a];
      if (n == 0)
        continue; /* sprite 0 is never drawn by map */
      if (layer && (p8_ram[P8_GFLAGS + n] & layer) != layer)
        continue;
      {
        int px = sx + i * 8, py = sy + j * 8;
        int u, v, s0 = (n % 16) * 8, t0 = (n / 16) * 8;
        for (v = 0; v < 8; v++)
          for (u = 0; u < 8; u++)
            p8i_ctx_sprite(&k, px + u, py + v, p8i_sheet_get(s0 + u, t0 + v));
      }
    }
  return 0;
}

/* ---- sheet/flag accessors ---- */

static int api_sget(lua_State *L)
{
  lua_pushnumber(L, (lua_Number)p8fix_fromint(
                        p8i_sheet_get(p8a_int(L, 1), p8a_int(L, 2))));
  return 1;
}

static int api_sset(lua_State *L)
{
  int x = p8a_int(L, 1), y = p8a_int(L, 2);
  int c = lua_isnoneornil(L, 3) ? p8_ram[P8_DS_PEN] : p8a_int(L, 3);
  p8i_sheet_set(x, y, (uint8_t)(c & 0x0F));
  return 0;
}

static int api_fget(lua_State *L)
{
  uint8_t f = p8_ram[P8_GFLAGS + (p8a_int(L, 1) & 0xFF)];
  if (lua_isnoneornil(L, 2)) {
    lua_pushnumber(L, (lua_Number)p8fix_fromint(f));
  } else {
    lua_pushboolean(L, (f >> (p8a_int(L, 2) & 7)) & 1);
  }
  return 1;
}

static int api_fset(lua_State *L)
{
  int n = p8a_int(L, 1) & 0xFF;
  if (lua_isnoneornil(L, 3)) {
    p8_ram[P8_GFLAGS + n] = (uint8_t)(p8a_int(L, 2) & 0xFF);
  } else {
    int bit = p8a_int(L, 2) & 7;
    if (lua_toboolean(L, 3))
      p8_ram[P8_GFLAGS + n] |= (uint8_t)(1 << bit);
    else
      p8_ram[P8_GFLAGS + n] &= (uint8_t)~(1 << bit);
  }
  return 0;
}

/* ---- palettes / fill pattern ---- */

static void pal_reset_draw(void)
{
  int i;
  for (i = 0; i < 16; i++)
    p8_ram[P8_DS_DRAWPAL + i] = (uint8_t)(i == 0 ? 0x10 : i);
}

static void pal_reset_screen(void)
{
  int i;
  for (i = 0; i < 16; i++)
    p8_ram[P8_DS_SCRNPAL + i] = (uint8_t)i;
}

static int api_pal(lua_State *L)
{
  if (lua_istable(L, 1)) {
    /* pal(tbl, [p]): apply table of c1 -> c2 */
    int p = p8a_optint(L, 2, 0);
    int c;
    for (c = 0; c < 16; c++) {
      lua_rawgeti(L, 1, c);
      if (!lua_isnil(L, -1)) {
        int c2 = (int)p8fix_toint((long)lua_tonumber(L, -1));
        if (p == 1)
          p8_ram[P8_DS_SCRNPAL + c] = (uint8_t)(c2 & 0xFF);
        else
          p8_ram[P8_DS_DRAWPAL + c] =
              (uint8_t)((p8_ram[P8_DS_DRAWPAL + c] & 0x10) | (c2 & 0x0F));
      }
      lua_pop(L, 1);
    }
    return 0;
  }
  if (lua_isnoneornil(L, 1)) {
    /* VERIFY: pal() resets draw+screen palettes and the fill pattern */
    pal_reset_draw();
    pal_reset_screen();
    p8_ram[0x5f31] = 0;
    p8_ram[0x5f32] = 0;
    p8_ram[0x5f33] = 0;
    return 0;
  }
  {
    int c1 = p8a_int(L, 1) & 0x0F;
    int c2 = p8a_int(L, 2);
    int p = p8a_optint(L, 3, 0);
    if (p == 1) {
      p8_ram[P8_DS_SCRNPAL + c1] = (uint8_t)(c2 & 0xFF);
    } else {
      /* VERIFY: transparency bit preserved across pal() remaps */
      p8_ram[P8_DS_DRAWPAL + c1] =
          (uint8_t)((p8_ram[P8_DS_DRAWPAL + c1] & 0x10) | (c2 & 0x0F));
    }
    return 0;
  }
}

static int api_palt(lua_State *L)
{
  int i;
  if (lua_isnoneornil(L, 1)) {
    for (i = 0; i < 16; i++)
      p8_ram[P8_DS_DRAWPAL + i] =
          (uint8_t)((p8_ram[P8_DS_DRAWPAL + i] & 0x0F) | (i == 0 ? 0x10 : 0));
    return 0;
  }
  if (lua_isnoneornil(L, 2) && lua_isnumber(L, 1)) {
    /* palt(bitfield): bit (15-c) = transparency of color c */
    unsigned int m = (unsigned int)p8a_int(L, 1) & 0xFFFFu;
    for (i = 0; i < 16; i++)
      p8_ram[P8_DS_DRAWPAL + i] =
          (uint8_t)((p8_ram[P8_DS_DRAWPAL + i] & 0x0F) |
                    (((m >> (15 - i)) & 1) ? 0x10 : 0));
    return 0;
  }
  {
    int c = p8a_int(L, 1) & 0x0F;
    if (lua_toboolean(L, 2))
      p8_ram[P8_DS_DRAWPAL + c] |= 0x10;
    else
      p8_ram[P8_DS_DRAWPAL + c] &= 0x0F;
    return 0;
  }
}

static int api_fillp(lua_State *L)
{
  long old = (long)p8_ram[0x5f31] | ((long)p8_ram[0x5f32] << 8);
  long v = lua_isnoneornil(L, 1) ? 0 : (long)lua_tonumber(L, 1);
  unsigned long raw = (unsigned long)(unsigned LUA_INT32)v & 0xffffffffu;
  p8_ram[0x5f31] = (uint8_t)((raw >> 16) & 0xFF);
  p8_ram[0x5f32] = (uint8_t)((raw >> 24) & 0xFF);
  /* fraction bits: 0b0.1 = secondary transparent, 0b0.01 = VERIFY
     (apply to sprites, not implemented) */
  p8_ram[0x5f33] = (uint8_t)(((raw >> 15) & 1) | ((raw >> 13) & 2));
  lua_pushnumber(L, (lua_Number)p8fix_fromint(old));
  return 1;
}

/* ---- cursor / print ---- */

static int api_cursor(lua_State *L)
{
  p8_ram[P8_DS_CURS_X] = (uint8_t)(p8a_optint(L, 1, 0) & 0xFF);
  p8_ram[P8_DS_CURS_Y] = (uint8_t)(p8a_optint(L, 2, 0) & 0xFF);
  if (!lua_isnoneornil(L, 3))
    p8_ram[P8_DS_PEN] = (uint8_t)(p8a_int(L, 3) & 0xFF);
  return 0;
}

static void screen_scroll(int lines)
{
  int bytes = lines * 64;
  memmove(&p8_ram[P8_SCREEN], &p8_ram[P8_SCREEN + bytes],
          (size_t)(0x2000 - bytes));
  memset(&p8_ram[P8_SCREEN + 0x2000 - bytes], 0, (size_t)bytes);
}

static int api_print(lua_State *L)
{
  size_t len, k;
  /* count args BEFORE luaL_tolstring pushes its copy: the copy sits at
     argc+1 and must not be mistaken for the color argument (the bug was
     print("ab") coercing "ab" to pen color 0 = invisible text) */
  int argc = lua_gettop(L);
  const char *s = luaL_tolstring(L, 1, &len);
  int cursor_mode = (argc < 3) || lua_isnil(L, 3);
  int x, y, home;
  if (cursor_mode) {
    x = p8_ram[P8_DS_CURS_X];
    y = p8_ram[P8_DS_CURS_Y];
    if (argc >= 2 && !lua_isnil(L, 2))
      p8_ram[P8_DS_PEN] = (uint8_t)(p8a_int(L, 2) & 0xFF);
  } else {
    x = p8a_int(L, 2);
    y = p8a_int(L, 3);
    if (argc >= 4 && !lua_isnil(L, 4))
      p8_ram[P8_DS_PEN] = (uint8_t)(p8a_int(L, 4) & 0xFF);
  }
  home = x;
  for (k = 0; k < len; k++) {
    unsigned char c = (unsigned char)s[k];
    if (c == '\n') {
      x = home;
      y += 6;
      continue;
    }
    /* VERIFY: P8SCII control codes (\^ etc.) unimplemented */
    if (cursor_mode && y > 122) {
      screen_scroll(y - 122);
      y = 122;
    }
    {
      int px, py;
      uint8_t pen = p8_ram[P8_DS_PEN];
      P8Ctx k;
      p8i_ctx_load(&k);   /* per glyph: screen_scroll moves rows, not state */
      for (py = 0; py < 8; py++) {
        uint8_t row = p8_font[c][py];
        if (!row)
          continue;
        for (px = 0; px < 8; px++)
          if ((row >> px) & 1)
            p8i_ctx_glyph(&k, x + px, y + py, pen);
      }
      x += (c < 128) ? 4 : 8;
    }
  }
  if (cursor_mode) {
    if (y > 122) {
      screen_scroll(6);
      y = 122;
    } else {
      y += 6;
    }
    p8_ram[P8_DS_CURS_X] = (uint8_t)home;
    p8_ram[P8_DS_CURS_Y] = (uint8_t)y;
  }
  lua_pop(L, 1); /* tolstring copy */
  lua_pushnumber(L, (lua_Number)p8fix_fromint(x));
  return 1;
}

/* C-callable text for the built-in cart menu (snes/p8main.c, -DP8_MULTICART):
** draw string s at (x,y) in raw color col (0..15) with the PICO-8 4px font,
** straight into the framebuffer -- no camera/clip/draw-palette/cursor. Clips
** to the 128x128 screen itself since p8i_screen_set does not bounds-check. */
void p8_text(int x, int y, unsigned char col, const char *s)
{
  int x0 = x;
  for (; *s; s++) {
    unsigned char c = (unsigned char)*s;
    int px, py;
    if (c == '\n') { x = x0; y += 6; continue; }
    for (py = 0; py < 8; py++) {
      unsigned char row = p8_font[c][py];
      if (!row)
        continue;
      for (px = 0; px < 8; px++)
        if ((row >> px) & 1) {
          int xx = x + px, yy = y + py;
          if ((unsigned)xx < 128u && (unsigned)yy < 128u)
            p8i_screen_set(xx, yy, (uint8_t)(col & 0x0F));
        }
    }
    x += (c < 128) ? 4 : 8;
  }
}

/* ---- btnp (held-frame counters advanced by p8_input_frame) ---- */

static int btnp_hit(int p, int b)
{
  int c = p8i_held[p][b];
  int delay = p8_ram[0x5f5c] ? p8_ram[0x5f5c] : 15; /* VERIFY 0=default */
  int ival = p8_ram[0x5f5d] ? p8_ram[0x5f5d] : 4;
  if (c == 1)
    return 1;
  if (p8_ram[0x5f5c] == 255)
    return 0; /* repeat disabled */
  return c > delay && ((c - 1 - delay) % ival) == 0;
}

static int api_btnp(lua_State *L)
{
  if (lua_isnoneornil(L, 1)) {
    unsigned int m = 0;
    int p, b;
    for (p = 0; p < 2; p++)
      for (b = 0; b < 8; b++)
        if (btnp_hit(p, b))
          m |= 1u << (p * 8 + b);
    lua_pushnumber(L, (lua_Number)p8fix_fromint((long)m));
    return 1;
  }
  {
    int b = p8a_int(L, 1) & 7;
    int p = p8a_optint(L, 2, 0) & 1;
    lua_pushboolean(L, btnp_hit(p, b));
    return 1;
  }
}

void p8_input_frame(void)
{
  int p, b;
  for (p = 0; p < 2; p++)
    for (b = 0; b < 8; b++) {
      if ((p8i_buttons[p] >> b) & 1) {
        if (p8i_held[p][b] < 255)
          p8i_held[p][b]++;
      } else {
        p8i_held[p][b] = 0;
      }
    }
}

/* ---- pause-menu registry + menuitem() (M8) ----
** menuitem() registers labels + Lua callbacks; the SNES pause overlay
** (snes/p8main.c) reads them and invokes a callback on selection. */

#define P8_MENU_MAX 5
static char p8_menu_txt[P8_MENU_MAX][20];  /* label text, NUL-terminated */
static int  p8_menu_ref[P8_MENU_MAX];      /* Lua callback ref, or LUA_NOREF */
static uint8_t p8_menu_on[P8_MENU_MAX];    /* slot active? */

/* clear the registry for a fresh lua_State (no unref -- the previous state,
** if any, is already closed). Called from p8gfx_open so each cart starts
** clean. */
void p8_menu_reset(void)
{
  int i;
  for (i = 0; i < P8_MENU_MAX; i++) {
    p8_menu_txt[i][0] = 0;
    p8_menu_ref[i] = LUA_NOREF;
    p8_menu_on[i] = 0;
  }
}

/* menuitem(index 1..5, [label], [callback]) -- register/replace/remove an
** entry. menuitem(i) with no label removes slot i. */
static int api_menuitem(lua_State *L)
{
  int idx = p8a_int(L, 1);
  int s;
  if (idx < 1 || idx > P8_MENU_MAX)
    return 0;
  s = idx - 1;
  if (p8_menu_ref[s] != LUA_NOREF) {
    luaL_unref(L, LUA_REGISTRYINDEX, p8_menu_ref[s]);
    p8_menu_ref[s] = LUA_NOREF;
  }
  if (lua_isnoneornil(L, 2)) {          /* remove */
    p8_menu_on[s] = 0;
    return 0;
  }
  {
    const char *lbl = lua_tostring(L, 2);
    size_t k = 0;
    if (lbl)
      for (; lbl[k] && k < sizeof(p8_menu_txt[0]) - 1; k++)
        p8_menu_txt[s][k] = lbl[k];
    p8_menu_txt[s][k] = 0;
  }
  if (lua_isfunction(L, 3)) {
    lua_pushvalue(L, 3);
    p8_menu_ref[s] = luaL_ref(L, LUA_REGISTRYINDEX);
  }
  p8_menu_on[s] = 1;
  return 0;
}

int p8_menu_count(void)
{
  int i, n = 0;
  for (i = 0; i < P8_MENU_MAX; i++)
    if (p8_menu_on[i])
      n++;
  return n;
}

/* label of the k-th active item (0-based over active items), or NULL */
const char *p8_menu_label(int k)
{
  int i;
  for (i = 0; i < P8_MENU_MAX; i++)
    if (p8_menu_on[i]) {
      if (k == 0)
        return p8_menu_txt[i];
      k--;
    }
  return 0;
}

/* invoke the k-th active item's callback; returns 1 if the menu should stay
** open (callback returned truthy), 0 to close. */
int p8_menu_invoke(lua_State *L, int k)
{
  int i, slot = -1;
  for (i = 0; i < P8_MENU_MAX; i++)
    if (p8_menu_on[i]) {
      if (k == 0) { slot = i; break; }
      k--;
    }
  if (slot < 0 || p8_menu_ref[slot] == LUA_NOREF)
    return 0;
  lua_rawgeti(L, LUA_REGISTRYINDEX, p8_menu_ref[slot]);
  lua_pushnumber(L, 0);                 /* PICO-8 passes a button bitmask; 0 */
  if (lua_pcall(L, 1, 1, 0) != LUA_OK) {
    lua_pop(L, 1);
    return 0;
  }
  {
    int stay = lua_toboolean(L, -1);
    lua_pop(L, 1);
    return stay;
  }
}

/* C-callable filled rect for the pause overlay (raw color, screen-clipped) */
void p8_fillrect(int x0, int y0, int x1, int y1, unsigned char col)
{
  int x, y;
  for (y = y0; y <= y1; y++) {
    if ((unsigned)y >= 128u)
      continue;
    for (x = x0; x <= x1; x++)
      if ((unsigned)x < 128u)
        p8i_screen_set(x, y, (uint8_t)(col & 0x0F));
  }
}

/* ---- stubs (sound lands in M6; the rest as needed) ---- */

static int stub_nop(lua_State *L)
{
  (void)L; /* VERIFY: music/sfx/menuitem/cstore/reload/extcmd no-ops */
  return 0;
}

static int api_cartdata(lua_State *L)
{
  (void)L; /* VERIFY: no persistence; 0x5e00 RAM only */
  lua_pushboolean(L, 1);
  return 1;
}

static int api_dget(lua_State *L)
{
  int i = p8a_int(L, 1);
  if (i >= 0 && i < 64) {
    unsigned int a = P8_PERSIST + (unsigned int)i * 4;
    uint32_t v = (uint32_t)p8_ram[a] | ((uint32_t)p8_ram[a + 1] << 8) |
                 ((uint32_t)p8_ram[a + 2] << 16) |
                 ((uint32_t)p8_ram[a + 3] << 24);
    lua_pushnumber(L, (lua_Number)(long)(int32_t)v);
  } else {
    lua_pushnumber(L, 0);
  }
  return 1;
}

static int api_dset(lua_State *L)
{
  int i = p8a_int(L, 1);
  if (i >= 0 && i < 64) {
    unsigned int a = P8_PERSIST + (unsigned int)i * 4;
    uint32_t v = (uint32_t)(long)lua_tonumber(L, 2);
    p8_ram[a] = (uint8_t)(v & 0xFF);
    p8_ram[a + 1] = (uint8_t)((v >> 8) & 0xFF);
    p8_ram[a + 2] = (uint8_t)((v >> 16) & 0xFF);
    p8_ram[a + 3] = (uint8_t)((v >> 24) & 0xFF);
  }
  return 0;
}

static int api_stat(lua_State *L)
{
  int n = p8a_optint(L, 1, 0);
  int av = p8_audio_stat(n);
  if (av != P8_STAT_NONE) {   /* stat(16..24): audio channel/pattern state */
    lua_pushnumber(L, (lua_Number)p8fix_fromint(av));
    return 1;
  }
  if (n == 0) {
    /* Lua memory used, in KB. This is a truthful number for a cart doing
       memory-pressure checks — but it is intentionally NOT host<->SNES
       parity-identical (the SNES uses smaller structs: TValue 8B vs 16,
       Node 20B vs 40), like the raw PRNG state at 0x5f44. We OOM near
       ~256 KB rather than PICO-8's 2048. */
    lua_pushnumber(L, (lua_Number)p8fix_fromint(lua_gc(L, LUA_GCCOUNT, 0)));
    return 1;
  }
  /* VERIFY: stat(1)/(2) CPU load and stat(4..) clipboard/gpio/date/etc.
     unimplemented — 0 (so carts that throttle on stat(1) don't degrade). */
  lua_pushnumber(L, 0);
  return 1;
}

static const luaL_Reg gfx_funcs[] = {
  { "line", api_line },
  { "rect", api_rect },
  { "rectfill", api_rectfill },
  { "circ", api_circ },
  { "circfill", api_circfill },
  { "oval", api_oval },
  { "ovalfill", api_ovalfill },
  { "spr", api_spr },
  { "sspr", api_sspr },
  { "map", api_map },
  { "mapdraw", api_map }, /* pre-0.1.11 alias */
  { "mget", api_mget },
  { "mset", api_mset },
  { "sget", api_sget },
  { "sset", api_sset },
  { "fget", api_fget },
  { "fset", api_fset },
  { "pal", api_pal },
  { "palt", api_palt },
  { "fillp", api_fillp },
  { "cursor", api_cursor },
  { "print", api_print },
  { "btnp", api_btnp },
  { "menuitem", api_menuitem },
  { "cstore", stub_nop },
  { "reload", stub_nop },
  { "extcmd", stub_nop },
  { "cartdata", api_cartdata },
  { "dget", api_dget },
  { "dset", api_dset },
  { "stat", api_stat },
  { NULL, NULL }
};

void p8gfx_open(lua_State *L)
{
  const luaL_Reg *r;
  p8_menu_reset();   /* fresh pause-menu registry per lua_State */
  for (r = gfx_funcs; r->name; r++)
    lua_register(L, r->name, r->func);
}
